d","grantee":"anon","grantor":"postgres","grantable":false,"privilege":"SELECT"},{"table":"rounds","column":"round_number","grantee":"anon","grantor":"postgres","grantable":false,"privilege":"SELECT"}]$columns$::jsonb OR replace(pg_get_functiondef('public.can_view_friendly_team_event_by_sides(uuid,uuid)'::regprocedure),chr(13),'') IS DISTINCT FROM replace($expected_function$CREATE OR REPLACE FUNCTION public.can_view_friendly_team_event_by_sides(p_event_id uuid, p_created_by_auth_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.is_super_user()
    or (p_created_by_auth_user_id = auth.uid() and exists (
 select 1 from public.events e where e.id=p_event_id and e.created_by_auth_user_id=auth.uid()
 and (e.club_id is null or exists (
  select 1 from public.club_members cm left join public.player_profiles pp on pp.id=cm.player_profile_id
  where cm.club_id=e.club_id and cm.is_active and (cm.profile_id=auth.uid() or pp.linked_auth_user_id=auth.uid())
 ))
))
    or exists (
      select 1
      from public.event_team_sides ets
      join public.club_members cm on cm.club_id = ets.club_id
      join public.player_profiles pp on pp.id = cm.player_profile_id
      where ets.event_id = p_event_id
        and cm.is_active = true
        and pp.linked_auth_user_id = auth.uid()
    )
    or exists (
      select 1
      from public.event_team_sides ets
      join public.club_members cm on cm.club_id = ets.club_id
      where ets.event_id = p_event_id
        and cm.is_active = true
        and cm.profile_id = auth.uid()
    );
$function$
$expected_function$,chr(13),'') THEN RAISE EXCEPTION 'SELECT post-state drifted; stop'; END IF; END $guard$;
CREATE OR REPLACE FUNCTION public.can_view_friendly_team_event_by_sides(p_event_id uuid, p_created_by_auth_user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select public.is_super_user()
    or p_created_by_auth_user_id = auth.uid()
    or exists (
      select 1
      from public.event_team_sides ets
      join public.club_members cm on cm.club_id = ets.club_id
      join public.player_profiles pp on pp.id = cm.player_profile_id
      where ets.event_id = p_event_id
        and cm.is_active = true
        and pp.linked_auth_user_id = auth.uid()
    )
    or exists (
      select 1
      from public.event_team_sides ets
      join public.club_members cm on cm.club_id = ets.club_id
      where ets.event_id = p_event_id
        and cm.is_active = true
        and cm.profile_id = auth.uid()
    );
$function$
;
ALTER POLICY events_public_shared_select ON public.events USING(((status = 'closed'::text) AND (share_enabled = true) AND (share_token IS NOT NULL) AND (COALESCE(is_deleted, false) = false)));
ALTER POLICY events_select_friendly_team_match_viewers ON public.events USING(((event_mode = 'team'::text) AND (COALESCE(is_deleted, false) = false) AND can_view_friendly_team_event_by_sides(id, created_by_auth_user_id)));
CREATE POLICY rls05_events_select_compat ON public.events FOR SELECT TO anon,authenticated USING(true);
DROP POLICY rls11_event_participants_select ON public.event_participants;
CREATE POLICY rls07_participants_select_compat ON public.event_participants FOR SELECT TO anon,authenticated USING(true);
DROP POLICY rls11_rounds_select ON public.rounds;
CREATE POLICY rls08_rounds_select_compat ON public.rounds FOR SELECT TO anon,authenticated USING(true);
DROP POLICY rls11_matches_select ON public.matches;
CREATE POLICY rls08_matches_select_compat ON public.matches FOR SELECT TO anon,authenticated USING(true);
DROP POLICY rls11_match_players_select ON public.match_players;
CREATE POLICY rls08_match_players_select_compat ON public.match_players FOR SELECT TO anon,authenticated USING(true);
DROP POLICY rls11_match_results_select ON public.match_results;
CREATE POLICY rls08_match_results_select_compat ON public.match_results FOR SELECT TO anon,authenticated USING(true);
REVOKE SELECT(id,name,created_at,status,is_deleted,share_enabled,club_id,event_mode,share_token) ON public.events FROM anon;
GRANT SELECT ON public.events TO anon;
REVOKE SELECT(id,event_id,guest_name,participant_type,player_profile_id,profile_id) ON public.event_participants FROM anon;
GRANT SELECT ON public.event_participants TO anon;
REVOKE SELECT(id,event_id,round_number) ON public.rounds FROM anon;
GRANT SELECT ON public.rounds TO anon;
REVOKE SELECT(id,event_id,round_id,court_number,completed,youtube_url,created_at) ON public.matches FROM anon;
GRANT SELECT ON public.matches TO anon;
REVOKE SELECT(id,match_id,participant_id,team) ON public.match_players FROM anon;
GRANT SELECT ON public.match_players TO anon;
REVOKE SELECT(id,match_id,score_a,score_b,winner_team) ON public.match_results FROM anon;
GRANT SELECT ON public.match_results TO anon;
ALTER POLICY event_team_sides_manage ON public.event_team_sides WITH CHECK(true);
ALTER POLICY event_team_matches_manage ON public.event_team_matches WITH CHECK(true);
COMMIT;
